# Perform BFS to find nodes at exactly depth 7
from collections import deque

def bfs_at_depth(graph, start, target_depth):
    # BFS to find nodes at exactly target_depth
    # Depth 0 is the start node itself
    # We want nodes at depth target_depth, not including start

    if target_depth == 0:
        return [start]

    visited = {start: 0}  # node -> depth
    queue = deque([start])
    nodes_at_depth = []

    while queue:
        current = queue.popleft()
        current_depth = visited[current]

        # If we've already passed target_depth, no need to continue
        if current_depth >= target_depth:
            continue

        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                visited[neighbor] = current_depth + 1
                if current_depth + 1 == target_depth:
                    nodes_at_depth.append(neighbor)
                queue.append(neighbor)

    return nodes_at_depth

# Find nodes at depth 7
result = bfs_at_depth(graph, start_node, 7)
print(f"Nodes at depth 7 from {start_node}: {result}")
print(f"Number of nodes at depth 7: {len(result)}")

# Let's also trace the BFS levels to verify
def trace_bfs(graph, start, max_depth):
    visited = {start: 0}
    queue = deque([start])
    levels = {0: [start]}

    while queue:
        current = queue.popleft()
        current_depth = visited[current]

        if current_depth >= max_depth:
            continue

        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                visited[neighbor] = current_depth + 1
                if current_depth + 1 not in levels:
                    levels[current_depth + 1] = []
                levels[current_depth + 1].append(neighbor)
                queue.append(neighbor)

    return levels

levels = trace_bfs(graph, start_node, 7)
for d in range(8):
    print(f"Depth {d}: {len(levels.get(d, []))} nodes")
    if d < 4:  # Show actual nodes for first few depths
        print(f"  Nodes: {levels.get(d, [])}")
